hooks.command:
jq -r '.tool_input.file_path // empty' | {
  read -r f
  case "$f" in
    */web/*) out=$(pnpm --dir web lint 2>&1); code=$? ;;
    */sync-server/*) out=$(pnpm --dir sync-server exec tsc --noEmit 2>&1); code=$? ;;
    */api/*) out=$(pnpm --dir api lint 2>&1); code=$? ;;
    *) exit 0 ;;
  esac
  if [ "$code" -ne 0 ]; then
    echo "$out" >&2
    exit 2
  fi
}
